```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Print orientation: flat on bed, top face up.

$fn = 128;

// --- Ring dimensions ---
outer_d     = 60;    // outer diameter of annulus
inner_d     = 36;    // inner diameter (bore)
thickness   = 4;     // ring thickness (Z)

// --- Tick marks ---
tick_count  = 12;    // number of evenly spaced ticks
tick_width  = 1.2;   // groove width
tick_depth  = 1.5;   // groove depth into top face
tick_length = 3;     // length inward from outer edge
tick_start_angle = 0; // first tick on +X axis

// --- Helpers ---
eps = 0.5;           // overcut past faces to avoid coplanar surfaces

outer_r = outer_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(d = outer_d, h = thickness);
        translate([0, 0, -eps])
            cylinder(d = inner_d, h = thickness + 2 * eps);
    }

    // Radial tick grooves
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, tick_start_angle + i * 360 / tick_count])
            translate([outer_r - tick_length,
                       -tick_width / 2,
                       thickness - tick_depth])
                cube([tick_length + eps, tick_width, tick_depth + eps]);
    }
}
```

```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Prints flat on the bed, centred on the origin.

// ---------------- Parameters ----------------
outer_d      = 60;    // ring outer diameter
inner_d      = 44;    // ring inner diameter (bore)
ring_h       = 5;     // ring thickness (Z)

tick_count   = 36;    // number of radial tick marks
tick_width   = 1.2;   // groove width (tangential)
tick_depth   = 1.5;   // groove depth into top face
tick_length  = 3;     // radial length, measured inward from outer edge
tick_start_angle = 0; // first tick on +X axis

eps          = 0.5;   // overcut so cutters pass through faces

$fn = 128;            // smoothness of curved surfaces

// ---------------- Derived ----------------
outer_r = outer_d / 2;
inner_r = inner_d / 2;
tick_r_inner = outer_r - tick_length;   // inner end of each tick

// ---------------- Model ----------------
difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_h, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_h + 2 * eps, r = inner_r);
    }

    // Radial tick grooves cut into the top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, tick_start_angle + i * 360 / tick_count])
            translate([tick_r_inner, -tick_width / 2, ring_h - tick_depth])
                cube([tick_length + eps, tick_width, tick_depth + eps]);
    }
}
```

