// ---------- Parameters ----------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_t     = 2;     // plate thickness (mm), z = 0..2

rib_count   = 5;     // number of ribs
rib_t       = 3;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate (mm), z = 2..6
rib_pitch   = plate_len / (rib_count + 1); // centre spacing = 20 mm

overlap     = 0.01;  // small overlap so ribs fuse into plate

$fn = 64;

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Ribs: centres at -40, -20, 0, 20, 40 mm
    for (i = [1 : rib_count]) {
        x_c = -plate_len/2 + i * rib_pitch;
        translate([x_c - rib_t/2, -plate_wid/2, plate_t - overlap])
            cube([rib_t, plate_wid, rib_h + overlap]);
    }
}
