// Powder measuring scoop - hemispherical bowl with flat handle
// Print orientation: bowl bottom on bed (z = 0), opening upward

$fn = 96;

// ---- Bowl ----
bowl_r_out   = 12;     // outer radius of bowl sphere
bowl_wall    = 1.5;    // bowl wall thickness
bowl_r_in    = bowl_r_out - bowl_wall;  // inner radius (10.5)
bowl_cz      = 12;     // sphere centre height (rim height)

// ---- Handle ----
handle_x0    = 10.5;   // handle start (X)
handle_x1    = 72;     // handle end (X)
handle_w     = 8;      // handle width (Y)
handle_t     = 4;      // handle thickness (Z)
handle_top   = 12;     // handle top face, flush with rim

eps          = 0.5;    // overcut for clean booleans

difference() {
    union() {
        // Outer half-sphere (lower half only)
        intersection() {
            translate([0, 0, bowl_cz]) sphere(r = bowl_r_out);
            translate([-bowl_r_out - eps, -bowl_r_out - eps, -eps])
                cube([2 * (bowl_r_out + eps), 2 * (bowl_r_out + eps), bowl_cz + eps]);
        }
        // Handle
        translate([handle_x0, -handle_w / 2, handle_top - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // Hollow out bowl cavity (extends above rim)
    translate([0, 0, bowl_cz]) sphere(r = bowl_r_in);
    // Remove anything of the outer sphere above the rim
    translate([-bowl_r_out - eps, -bowl_r_out - eps, bowl_cz])
        cube([2 * (bowl_r_out + eps), 2 * (bowl_r_out + eps), bowl_r_out + eps]);
}
