bowl_wall      = 2;     // bowl wall thickness
bowl_inner_r   = bowl_outer_r - bowl_wall; // inner radius (10 mm)
bowl_center_z  = 12;    // sphere centre height (= rim height)

handle_x_start = 10;    // handle start along +X
