$fn = 128;              // smoothness of curved surfaces

// ---------- Modules ----------
module bowl() {
    difference() {
        translate([0, 0, bowl_center_z]) sphere(r = bowl_outer_r);
        // hollow interior
        translate([0, 0, bowl_center_z]) sphere(r = bowl_inner_r);
        // remove upper half (everything above the rim)
        translate([-(bowl_outer_r + eps), -(bowl_outer_r + eps), bowl_center_z])
            cube([2 * (bowl_outer_r + eps), 2 * (bowl_outer_r + eps), bowl_outer_r + eps]);
    }
}

module handle() {
    translate([handle_x_start, -handle_width / 2, handle_bot_z])
        cube([handle_x_end - handle_x_start, handle_width, handle_thick]);
}

// ---------- Assembly ----------
difference() {
    union() {
        bowl();
        handle();
    }
    // keep bowl cavity clear of any handle material
    translate([0, 0, bowl_center_z]) sphere(r = bowl_inner_r);
