// Pin hinge leaf - one half of a pin hinge
// Print orientation: plate flat on the bed, knuckles upward along +Y edge

$fn = 96;

// ---------- Plate ----------
plate_len   = 40;    // X length of leaf plate
plate_wid   = 20;    // Y width of leaf plate
plate_thk   = 2.5;   // Z thickness of leaf plate

// ---------- Knuckles ----------
num_segments = 5;                          // length divided into equal segments
seg_len      = plate_len / num_segments;   // 8 mm per segment
knuckle_d    = 6;                          // knuckle outer diameter
knuckle_y    = 10;                         // knuckle axis Y position
knuckle_z    = 3;                          // knuckle axis Z position
knuckle_idx  = [0, 2, 4];                  // 1st, 3rd, 5th segments (0-based)

// ---------- Pin hole ----------
pin_d        = 2.5;  // pin hole diameter
cut_ext      = 1;    // extra length for clean cuts

difference() {
    union() {
        // Flat plate, centred on origin in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on alternating segments
        for (i = knuckle_idx)
            translate([-plate_len/2 + i*seg_len, knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole along the common knuckle axis, through all knuckles
    translate([-plate_len/2 - cut_ext, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*cut_ext);
}
