// Star-shaped indexing wheel
// Flat 8-pointed star plate with a central through-hole

// ---------------- Parameters ----------------
n_points     = 8;    // number of star points
r_outer      = 30;   // radius of outer (tip) points, mm
r_inner      = 15;   // radius of inner (valley) points, mm
thickness    = 5;    // plate thickness, mm
hole_d       = 8;    // central hole diameter, mm
cut_extra    = 0.5;  // extension of cutting shapes past faces, mm
$fn          = 96;   // facet count for curved shapes

// ---------------- Derived ----------------
step = 360 / (2 * n_points);   // angle between successive outline vertices

// Outline vertices: alternating outer/inner, first outer point on +X
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (r = (i % 2 == 0) ? r_outer : r_inner,
             a = i * step)
        [r * cos(a), r * sin(a)]
];

// ---------------- Model ----------------
difference() {
    // Star plate resting on the bed
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = thickness + 2 * cut_extra);
}
