// Tapered riser block for raising a beaker
// Solid square frustum with a square pocket in the top face

// ---------------- Dimensions (mm) ----------------
base_side    = 60;   // bottom square side length at z = 0
top_side     = 40;   // top square side length at z = height
height       = 30;   // overall height of the frustum

pocket_side  = 30;   // square pocket side length
pocket_depth = 5;    // pocket depth from top face

overcut      = 0.5;  // extension of cutting shapes past faces

// ---------------- Derived ----------------
hb = base_side / 2;
ht = top_side / 2;

// ---------------- Model ----------------
difference() {
    // Square frustum built from 8 corner points
    polyhedron(
        points = [
            [-hb, -hb, 0], [ hb, -hb, 0], [ hb,  hb, 0], [-hb,  hb, 0],          // bottom
            [-ht, -ht, height], [ ht, -ht, height], [ ht,  ht, height], [-ht,  ht, height] // top
        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 5, 1, 0],   // front (-Y)
            [5, 6, 2, 1],   // right (+X)
            [6, 7, 3, 2],   // back (+Y)
            [7, 4, 0, 3],   // left (-X)
            [7, 6, 5, 4]    // top
        ]
    );

    // Centred square pocket in the top face
    translate([-pocket_side / 2, -pocket_side / 2, height - pocket_depth])
        cube([pocket_side, pocket_side, pocket_depth + overcut]);
}
