rim_id      = rim_od - 2 * rim_width;   // rim inner diameter (72)
spoke_start = hub_d / 2 - eps;          // spoke begins inside hub
spoke_end   = rim_id / 2 + eps;         // spoke ends inside rim
spoke_len   = spoke_end - spoke_start;

difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, thickness]);
    }

    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
