// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, z = 0 up to thickness

// ---------- Parameters ----------
thickness     = 5;    // overall part thickness (Z)
rim_od        = 100;  // outer diameter of rim
rim_width     = 6;    // radial width of rim ring
hub_d         = 16;   // hub outer diameter
axle_d        = 6;    // axle hole diameter
spoke_count   = 5;    // number of spokes
spoke_width   = 4;    // spoke width
spoke_start   = 0;    // angle of first spoke (deg, +X axis)
eps           = 0.5;  // cutter overshoot
$fn           = 128;

// ---------- Derived ----------
rim_id        = rim_od - 2 * rim_width;   // inner diameter of rim
spoke_r0      = hub_d / 2 - 1;            // spoke start radius (overlaps hub)
spoke_r1      = rim_id / 2 + 1;           // spoke end radius (overlaps rim)

// ---------- Model ----------
difference() {
    union() {
        // Rim ring
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([spoke_r0, -spoke_width / 2, 0])
                    cube([spoke_r1 - spoke_r0, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
